from functools import lru_cache
from openai import OpenAI


@lru_cache(maxsize=1)
def get_client() -> OpenAI:
    return OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))


def get_model_name(task: str) -> str:
    mapping = {
        "summary": os.environ.get("OPENAI_SUMMARY_MODEL", "gpt-4.1-mini"),
        "extract": os.environ.get("OPENAI_EXTRACT_MODEL", "gpt-4.1-mini"),
        "qa": os.environ.get("OPENAI_QA_MODEL", "gpt-4.1-mini"),
        "stream": os.environ.get("OPENAI_STREAM_MODEL", "gpt-4.1-mini"),
        "safety": os.environ.get("OPENAI_SAFETY_MODEL", "gpt-4.1-mini"),
        "translate": os.environ.get("OPENAI_TRANSLATE_MODEL", "gpt-4.1-mini"),
        "embed": os.environ.get("OPENAI_EMBED_MODEL", "text-embedding-3-large"),
        "spoken": os.environ.get("OPENAI_SPOKEN_MODEL", "gpt-4.1-mini"),
    }
    return mapping.get(task, os.environ.get("OPENAI_DEFAULT_MODEL", "gpt-4.1-mini"))
","model_models.py":"from __future__ import annotations

from dataclasses import dataclass
import json
from typing import Any


@dataclass
class BuildTextRequest:
    task: str
    input_text: str
    max_sentences: int | None = None
    schema_hint: str | None = None

    def to_prompt(self) -> str:
        parts = [f"Task: {self.task}", f"Input: {self.input_text}"]
        if self.max_sentences is not None:
            parts.append(f"Max sentences: {self.max_sentences}")
        if self.schema_hint:
            parts.append(f"Schema hint: {self.schema_hint}")
        return "\n".join(parts)


@dataclass
class QARequest:
    question: str
    context: str

    def to_prompt(self) -> str:
        return f"Context:\n{self.context}\n\nQuestion: {self.question}"


@dataclass
class StreamPromptRequest:
    prompt: str


@dataclass
class BaseTextResult:
    text: str
    model: str

    @classmethod
    def from_text(cls, text: str, model: str):
        return cls(text=text, model=model)


@dataclass
class SummarizeResult(BaseTextResult):
    pass


@dataclass
class QAResult(BaseTextResult):
    pass


@dataclass
class JsonExtractionResult:
    data: Any
    model: str

    @classmethod
    def from_text(cls, text: str, model: str):
        try:
            data = json.loads(text)
        except Exception:
            data = {"raw": text}
        return cls(data=data, model=model)
